CREATE TABLE IF NOT EXISTS tenants (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('sponsor','organizer','sandbox')));
CREATE TABLE IF NOT EXISTS principals (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), role text NOT NULL CHECK(role IN ('buyer','seller','operator')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, principal_id text NOT NULL REFERENCES principals(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS agent_wallets (id text PRIMARY KEY, principal_id text REFERENCES principals(id), tenant_id text NOT NULL REFERENCES tenants(id), role text NOT NULL, address text UNIQUE NOT NULL, encrypted_key text NOT NULL, next_nonce bigint);
CREATE TABLE IF NOT EXISTS missions (id text PRIMARY KEY, principal_id text NOT NULL REFERENCES principals(id), tenant_id text NOT NULL REFERENCES tenants(id), objective text NOT NULL, brief text NOT NULL, sports jsonb NOT NULL, package_budget_cents bigint NOT NULL, budget_wei numeric(78,0) NOT NULL CHECK(budget_wei >= 0), gas_budget_wei numeric(78,0) NOT NULL, status text NOT NULL DEFAULT 'created', state jsonb NOT NULL DEFAULT '{}', steps integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_events (id bigserial PRIMARY KEY, mission_id text NOT NULL REFERENCES missions(id), actor text NOT NULL, kind text NOT NULL, summary text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), sport_id text NOT NULL, public_metadata jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), event_id text NOT NULL REFERENCES events(id), commitment text NOT NULL, encrypted_payload text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_accounts (id text NOT NULL, snapshot_id text NOT NULL REFERENCES snapshots(id), organizer_id text NOT NULL, geography text, PRIMARY KEY(snapshot_id,id));
CREATE TABLE IF NOT EXISTS source_blocks (id text NOT NULL, snapshot_id text NOT NULL REFERENCES snapshots(id), edition_id text NOT NULL, kind text NOT NULL, starts_at text NOT NULL, status text NOT NULL, schedule_version integer NOT NULL, PRIMARY KEY(snapshot_id,id));
CREATE TABLE IF NOT EXISTS source_entitlements (id text NOT NULL, snapshot_id text NOT NULL REFERENCES snapshots(id), account_id text NOT NULL, block_id text NOT NULL, zone_id text, category text NOT NULL, status text NOT NULL, product_type text NOT NULL, PRIMARY KEY(snapshot_id,id));
CREATE TABLE IF NOT EXISTS source_observations (id text NOT NULL, snapshot_id text NOT NULL REFERENCES snapshots(id), subject_id text NOT NULL, block_id text NOT NULL, zone_id text, kind text NOT NULL, occurred_at text NOT NULL, accepted boolean NOT NULL, PRIMARY KEY(snapshot_id,id));
CREATE TABLE IF NOT EXISTS source_entries (id text NOT NULL, snapshot_id text NOT NULL REFERENCES snapshots(id), participant_id text NOT NULL, account_id text NOT NULL, edition_id text NOT NULL, distance text NOT NULL, wave text NOT NULL, status text NOT NULL, PRIMARY KEY(snapshot_id,id));
CREATE TABLE IF NOT EXISTS source_coverage (id bigserial PRIMARY KEY, snapshot_id text NOT NULL REFERENCES snapshots(id), block_id text NOT NULL, zone_id text, kind text NOT NULL, status text NOT NULL, reason text);
CREATE TABLE IF NOT EXISTS offers (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), event_id text NOT NULL REFERENCES events(id), snapshot_id text NOT NULL REFERENCES snapshots(id), manifest jsonb NOT NULL, terms_hash text NOT NULL, report_commitment text NOT NULL, encrypted_artifact text NOT NULL, publication_key text UNIQUE NOT NULL, chain_offer_id text, publication_tx text, allowed_principal text REFERENCES principals(id), status text NOT NULL DEFAULT 'prepared');
CREATE TABLE IF NOT EXISTS market_orders (id text PRIMARY KEY, mission_id text NOT NULL REFERENCES missions(id), principal_id text NOT NULL REFERENCES principals(id), offer_id text NOT NULL REFERENCES offers(id), chain_order_id text, funding_tx text, delivery_tx text, outcome_tx text, withdrawal_tx text, status text NOT NULL DEFAULT 'queued', access_active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(principal_id,offer_id));
CREATE TABLE IF NOT EXISTS budget_reservations (id text PRIMARY KEY, mission_id text NOT NULL REFERENCES missions(id), offer_id text NOT NULL REFERENCES offers(id), price_wei numeric(78,0) NOT NULL CHECK(price_wei>0), status text NOT NULL CHECK(status IN ('reserved','spent','refunded','released')), UNIQUE(mission_id,offer_id));
CREATE TABLE IF NOT EXISTS wallet_transactions (id text PRIMARY KEY, wallet_id text NOT NULL REFERENCES agent_wallets(id), nonce bigint NOT NULL, purpose text NOT NULL, tx_hash text NOT NULL UNIQUE, encrypted_raw text NOT NULL, status text NOT NULL DEFAULT 'signed', receipt jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(wallet_id,nonce));
CREATE TABLE IF NOT EXISTS verification_runs (id text PRIMARY KEY, order_id text NOT NULL REFERENCES market_orders(id), valid boolean NOT NULL, checks jsonb NOT NULL, evidence_commitment text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS query_releases (tenant_id text NOT NULL REFERENCES tenants(id), event_id text NOT NULL, template_id text NOT NULL, lattice_key text NOT NULL, offer_id text NOT NULL REFERENCES offers(id), PRIMARY KEY(tenant_id,event_id,template_id,lattice_key));
CREATE TABLE IF NOT EXISTS custom_requests (id text PRIMARY KEY, mission_id text NOT NULL REFERENCES missions(id), event_id text NOT NULL REFERENCES events(id), question text NOT NULL, scope jsonb NOT NULL, status text NOT NULL, response jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_owner text, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(status,run_at);
CREATE TABLE IF NOT EXISTS tool_executions (mission_id text NOT NULL, call_id text NOT NULL, name text NOT NULL, output jsonb, status text NOT NULL, PRIMARY KEY(mission_id,call_id));
CREATE TABLE IF NOT EXISTS chain_cursors (chain_id integer PRIMARY KEY, next_block numeric(78,0) NOT NULL);
CREATE TABLE IF NOT EXISTS indexed_logs (chain_id integer NOT NULL, tx_hash text NOT NULL, log_index integer NOT NULL, block_number numeric(78,0) NOT NULL, block_hash text NOT NULL, event_name text NOT NULL, args jsonb NOT NULL, canonical boolean NOT NULL DEFAULT true, PRIMARY KEY(chain_id,tx_hash,log_index));
CREATE TABLE IF NOT EXISTS worker_health (id text PRIMARY KEY, heartbeat_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS market_chain_cursors(chain_id int,market_address text,next_block numeric(78,0),updated_at timestamptz DEFAULT now(),PRIMARY KEY(chain_id,market_address));
CREATE TABLE IF NOT EXISTS market_indexed_logs(chain_id int,market_address text,tx_hash text,log_index int,block_number numeric(78,0),block_hash text,block_timestamp bigint,event_name text,args jsonb,canonical boolean DEFAULT true,PRIMARY KEY(chain_id,market_address,tx_hash,log_index));
CREATE TABLE IF NOT EXISTS market_indexed_blocks(chain_id int,market_address text,block_number numeric(78,0),block_hash text,PRIMARY KEY(chain_id,market_address,block_number));
ALTER TABLE snapshots ADD COLUMN IF NOT EXISTS encrypted_salt text;
CREATE TABLE IF NOT EXISTS chain_instance (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),chain_id integer NOT NULL,market_address text NOT NULL,mode text NOT NULL);
